using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using System.Runtime.Serialization;
[DataContract] sealed class BossTradeRow {[DataMember] public string Text,Action;}
[DataContract] sealed class BossTradeView {[DataMember] public string Notice;[DataMember] public List<BossTradeRow> Rows=new();}
public partial class MigrationScene {
 sealed class BossOffer {public string Id,From,To,Item;public double Until;}
 readonly List<BossOffer> bossOffers=new();BossTradeView bossTradeView=new();
 double TradeTime=>Time.GetTicksMsec()/1000.0;
 string TradeName(ExpeditionGame g)=>coopActors.Values.FirstOrDefault(a=>a.Game==g)?.Name??"Host";
 BossTradeView MakeBossTradeView(ExpeditionGame who){var view=new BossTradeView{Notice=who.Notice};var people=MillPlayers();var self=people.FirstOrDefault(p=>p.Game==who);foreach(var item in who.BossTradeItems().Where(i=>i.Bond!=null)){foreach(var peer in people.Where(p=>p.Game!=who&&p.Game.Life.Health>0&&Distance(p.Body.Position,self.Body.Position)<=6&&item.Bond.Allows(p.Game.Life.SoulOwner))){string reason=who.BossTradeReason(item.Id,peer.Game);view.Rows.Add(new(){Text=item.Name+" TO "+TradeName(peer.Game)+(reason=="Ready"?"":" / "+reason),Action=reason=="Ready"?"offer|"+item.Id+"|"+peer.Game.Life.SoulOwner:""});}}
  foreach(var offer in bossOffers.Where(o=>o.Until>TradeTime&&(o.To==who.Life.SoulOwner||o.From==who.Life.SoulOwner))){var giver=people.FirstOrDefault(p=>p.Game.Life.SoulOwner==offer.From).Game;var item=giver?.BossTradeItems().Find(i=>i.Id==offer.Item);if(item==null)continue;bool incoming=offer.To==who.Life.SoulOwner;view.Rows.Add(new(){Text=(incoming?"ACCEPT FROM "+TradeName(giver):"PENDING")+" / "+item.Name,Action=incoming?"accept|"+offer.Id:""});view.Rows.Add(new(){Text=incoming?"DECLINE OFFER":"CANCEL OFFER",Action="cancel|"+offer.Id});}return view;}
 void ShowBossTrades(){coopMenu="bosstrade";if(!CoopRequest("bosstrade","view"))bossTradeView=MakeBossTradeView(game);DrawBossTrades();}
 void DrawBossTrades(){var b=Panel("BOSS LOOT / KILL-GROUP TRADING");coopMenu="bosstrade";Text(b,"Give a boss item to another original kill-group member within 6m. They must accept within 60 seconds. Unequip or uninstall it first. Stats and the original eligible group never change. No trading deadline on the item itself; old items without a recorded group remain bound.");if(bossTradeView.Rows.Count==0)Text(b,"No nearby eligible recipients or pending offers. Both players can open this screen from Inventory > Soulbound armory.");foreach(var row in bossTradeView.Rows){string action=row.Action;PackLabel(b,row.Text,13);if(!string.IsNullOrEmpty(action))Button(b,action.StartsWith("offer|")?"OFFER THIS ITEM":action.StartsWith("accept|")?"ACCEPT THIS ITEM":"CLOSE OFFER",()=>{if(!CoopRequest("bosstrade",action)){BossTradeAction(action);bossTradeView=MakeBossTradeView(game);DrawBossTrades();}});}Text(b,bossTradeView.Notice);Button(b,"REFRESH",ShowBossTrades);Button(b,"BACK",ShowSoulArmory);}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void BossTradeSnapshot(string json){if(!CoopClient)return;bossTradeView=Json.Read<BossTradeView>(json);if(paused&&coopMenu=="bosstrade")DrawBossTrades();else game.Notice="Boss loot offer updated / Inventory > Soulbound armory > Trade";}
 void SyncBossTrades(){if(!CoopHost)return;foreach(var a in coopActors.Values){SendCoopPersonal(a.Id,CoopProfileJson(a.Game),a.Game.Notice,a.Body.Position,false);RpcId(a.Id,nameof(BossTradeSnapshot),Json.Write(MakeBossTradeView(a.Game)));}}
 void BossTradeAction(string data){if(CoopClient||data.Length>240)return;bossOffers.RemoveAll(o=>o.Until<=TradeTime);var bits=data.Split('|');var people=MillPlayers();var self=people.FirstOrDefault(p=>p.Game==game);if(self.Body==null)return;
  if(bits[0]=="offer"&&bits.Length==3){var target=people.FirstOrDefault(p=>p.Game.Life.SoulOwner==bits[2]);string why=game.BossTradeReason(bits[1],target.Game);if(why!="Ready")game.Notice=why;else if(target.Body==null||game.Life.Health<=0||target.Game.Life.Health<=0||Distance(self.Body.Position,target.Body.Position)>6)game.Notice="Both survivors must be alive and within 6m";else{bossOffers.RemoveAll(o=>o.From==game.Life.SoulOwner&&o.Item==bits[1]);bossOffers.Add(new(){Id=Guid.NewGuid().ToString("N"),From=game.Life.SoulOwner,To=bits[2],Item=bits[1],Until=TradeTime+60});game.Notice="Offer sent / waiting for acceptance";target.Game.Notice="Boss loot offer received / open Soulbound armory > Trade";}}
  else if(bits[0]=="accept"&&bits.Length==2){var offer=bossOffers.FirstOrDefault(o=>o.Id==bits[1]&&o.To==game.Life.SoulOwner);if(offer==null)game.Notice="Offer expired or unavailable";else{var sender=people.FirstOrDefault(p=>p.Game.Life.SoulOwner==offer.From);if(sender.Body==null||sender.Game.Life.Health<=0||game.Life.Health<=0||Distance(sender.Body.Position,self.Body.Position)>6)game.Notice="Both survivors must be alive and within 6m";else if(sender.Game.TransferBossItem(offer.Item,game))bossOffers.RemoveAll(o=>o.Item==offer.Item);else game.Notice=sender.Game.Notice;}}
  else if(bits[0]=="cancel"&&bits.Length==2){bossOffers.RemoveAll(o=>o.Id==bits[1]&&(o.From==game.Life.SoulOwner||o.To==game.Life.SoulOwner));game.Notice="Offer closed";}
  if(bits[0]=="view"){if(coopActor>0)RpcId(coopActor,nameof(BossTradeSnapshot),Json.Write(MakeBossTradeView(game)));return;}SyncBossTrades();
 }
}
